diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.test.ts b/csv.test.ts
--- a/csv.test.ts	2026-10-29 11:00:33.293462769 +0000
+++ b/csv.test.ts	2026-10-29 11:03:22.693361748 +0000
@@ -23,3 +23,137 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+function streamRows(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of chunks) rows.push(...s.push(c));
+  rows.push(...s.end());
+  return rows;
+}
+
+// Every way of cutting `text` into two chunks, and into one-character chunks.
+function everySplit(text: string): string[][] {
+  const splits: string[][] = [[text]];
+  for (let i = 0; i <= text.length; i++) splits.push([text.slice(0, i), text.slice(i)]);
+  splits.push([...text]);
+  return splits;
+}
+
+test("the stream agrees with parseCsv for every split of fixed inputs", () => {
+  const inputs = ['a,b\r\n"x,""y""",z\n', "a\n\nb", "a,\n,\r\n", "\n", "\uFEFFa\n\uFEFFb", '"a""\r\n"', "a\r", '""', ",", "\r"];
+  for (const text of inputs) {
+    for (const chunks of everySplit(text)) expect(streamRows(chunks)).toEqual(parseCsv(text));
+  }
+});
+
+test("a row end split between \\r and \\n is one row end", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+});
+
+test("a \\r not followed by \\n stays in its field, also at a chunk or input end", () => {
+  expect(streamRows(["a\r", "b\n"])).toEqual([["a\rb"]]);
+  expect(streamRows(["a\r"])).toEqual([["a\r"]]);
+  expect(streamRows(["\r"])).toEqual([["\r"]]);
+});
+
+test("quoted fields and doubled quotes can span chunks", () => {
+  expect(streamRows(['"x"', '"y"\n'])).toEqual([['x"y']]);
+  expect(streamRows(['"x"', '"', 'y"\n'])).toEqual([['x"y']]);
+  expect(streamRows(['"a\r', '\nb"'])).toEqual([["a\r\nb"]]);
+});
+
+test("a quoted field may be followed by a row end split across chunks", () => {
+  expect(streamRows(['"a"\r', "\nb"])).toEqual([["a"], ["b"]]);
+});
+
+test("rejects text after a closing quote for every split", () => {
+  for (const text of ['"a"b', '"a"\rb', '"a"\r\rb\n', 'x,"a"\r"']) {
+    for (const chunks of everySplit(text)) expect(() => streamRows(chunks)).toThrow(SyntaxError);
+  }
+});
+
+test("a quote in an unquoted field throws, also right after a \\r", () => {
+  expect(() => streamRows(["a", '"b'])).toThrow(SyntaxError);
+  expect(() => streamRows(['a"b'])).toThrow(SyntaxError);
+  expect(() => streamRows(['a\r"'])).toThrow(SyntaxError);
+});
+
+test("a quoted field still open at the end throws from end()", () => {
+  const s = new CsvStream();
+  expect(s.push('"ab')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a closing quote at the end of the input is a complete field", () => {
+  expect(streamRows(['"a"'])).toEqual([["a"]]);
+});
+
+test("a BOM is dropped only at the very start, even after empty chunks", () => {
+  expect(streamRows(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(streamRows(["a\n\uFEFFb"])).toEqual([["a"], ["\uFEFFb"]]);
+  expect(streamRows(["\uFEFF"])).toEqual([]);
+});
+
+test("empty input, a trailing row end and empty lines", () => {
+  expect(streamRows([])).toEqual([]);
+  expect(streamRows([""])).toEqual([]);
+  expect(streamRows(["a\n"])).toEqual([["a"]]);
+  expect(streamRows(["\n"])).toEqual([[""]]);
+  expect(streamRows(["a,"])).toEqual([["a", ""]]);
+});
+
+test("a row is returned as soon as its row end arrives", () => {
+  const s = new CsvStream();
+  expect(s.push("a\n")).toEqual([["a"]]);
+  expect(s.push('"b')).toEqual([]);
+});
+
+test("random inputs and chunkings agree with parseCsv", () => {
+  let seed = 12345;
+  const rand = (n: number) => {
+    seed = (Math.imul(seed, 1103515245) + 12345) >>> 0;
+    return (seed >>> 16) % n;
+  };
+  const alphabet = ['a', ",", '"', "\r", "\n", "\uFEFF"];
+  const texts = new Set<string>();
+  for (let t = 0; t < 2000; t++) {
+    let text = "";
+    for (let n = rand(31); n > 0; n--) text += alphabet[rand(alphabet.length)];
+    texts.add(text);
+    const chunks: string[] = [];
+    let at = 0;
+    while (at < text.length) {
+      if (rand(4) === 0) chunks.push("");
+      const size = 1 + rand(5);
+      chunks.push(text.slice(at, at + size));
+      at += size;
+    }
+    let expected: string[][] | undefined;
+    try {
+      expected = parseCsv(text);
+    } catch (e) {
+      expect(e).toBeInstanceOf(SyntaxError);
+    }
+    if (expected === undefined) expect(() => streamRows(chunks)).toThrow(SyntaxError);
+    else expect(streamRows(chunks)).toEqual(expected);
+  }
+  expect(texts.size).toBeGreaterThan(1500);
+});
+
+test("work per chunk does not grow with the input", () => {
+  // One open quoted field fed one character per chunk: a version that re-reads what it has buffered
+  // would take quadratic time here, while the field is never emptied.
+  const s = new CsvStream();
+  const start = performance.now();
+  expect(s.push('"')).toEqual([]);
+  for (let i = 1; i <= 1_000_000; i++) {
+    expect(s.push("a")).toEqual([]);
+    if (i % 100_000 === 0) expect(performance.now() - start).toBeLessThan(5000);
+  }
+  expect(s.push('"\n')).toEqual([["a".repeat(1_000_000)]]);
+  expect(s.end()).toEqual([]);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 11:00:33.293595731 +0000
+++ b/csv.ts	2026-10-29 11:01:49.397356202 +0000
@@ -50,3 +50,109 @@
   rows.push(row);
   return rows;
 }
+
+type State = "start" | "unquoted" | "unquotedCR" | "quoted" | "quotedQuote" | "afterCloseCR";
+
+/** Streams `parseCsv`: the rows from all calls together equal `parseCsv` of the whole input, for any split. */
+export class CsvStream {
+  private row: string[] = [];
+  private field = "";
+  private state: State = "start";
+  private offset = 0;
+
+  push(chunk: string): string[][] {
+    const rows: string[][] = [];
+    for (let k = 0; k < chunk.length; k++) {
+      const at = this.offset++;
+      if (at === 0 && chunk[k] === "﻿") continue;
+      this.step(chunk[k]!, at, rows);
+    }
+    return rows;
+  }
+
+  end(): string[][] {
+    const rows: string[][] = [];
+    switch (this.state) {
+      case "start":
+        if (this.row.length > 0) this.endRow(rows);
+        break;
+      case "unquoted":
+      case "quotedQuote":
+        this.endRow(rows);
+        break;
+      case "unquotedCR":
+        this.field += "\r";
+        this.endRow(rows);
+        break;
+      case "quoted":
+        throw new SyntaxError("a quoted field is still open at the end of the input");
+      case "afterCloseCR":
+        throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.offset - 1}`);
+    }
+    this.row = [];
+    this.field = "";
+    this.state = "start";
+    this.offset = 0;
+    return rows;
+  }
+
+  private step(c: string, at: number, rows: string[][]): void {
+    switch (this.state) {
+      case "start":
+        if (c === '"') this.state = "quoted";
+        else if (c === "\r") this.state = "unquotedCR";
+        else if (c === "\n") this.endRow(rows);
+        else if (c === ",") this.finishField();
+        else {
+          this.field += c;
+          this.state = "unquoted";
+        }
+        return;
+      case "unquoted":
+        if (c === "\r") this.state = "unquotedCR";
+        else if (c === "\n") this.endRow(rows);
+        else if (c === ",") this.finishField();
+        else if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${at}`);
+        else this.field += c;
+        return;
+      case "unquotedCR":
+        if (c === "\n") {
+          this.endRow(rows);
+          return;
+        }
+        this.field += "\r";
+        this.state = "unquoted";
+        this.step(c, at, rows);
+        return;
+      case "quoted":
+        if (c === '"') this.state = "quotedQuote";
+        else this.field += c;
+        return;
+      case "quotedQuote":
+        if (c === '"') {
+          this.field += '"';
+          this.state = "quoted";
+        } else if (c === ",") this.finishField();
+        else if (c === "\n") this.endRow(rows);
+        else if (c === "\r") this.state = "afterCloseCR";
+        else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${at}`);
+        return;
+      case "afterCloseCR":
+        if (c !== "\n") throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${at - 1}`);
+        this.endRow(rows);
+        return;
+    }
+  }
+
+  private finishField(): void {
+    this.row.push(this.field);
+    this.field = "";
+    this.state = "start";
+  }
+
+  private endRow(rows: string[][]): void {
+    this.finishField();
+    rows.push(this.row);
+    this.row = [];
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.test.ts b/csv.test.ts
--- a/csv.test.ts	2026-10-29 11:00:33.306316666 +0000
+++ b/csv.test.ts	2026-10-29 11:02:23.981358258 +0000
@@ -23,3 +23,90 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+function run(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of chunks) rows.push(...s.push(c));
+  rows.push(...s.end());
+  return rows;
+}
+
+// The result of f: its rows, or its SyntaxError message.
+function outcome(f: () => string[][]): unknown {
+  try {
+    return f();
+  } catch (e) {
+    return e instanceof SyntaxError ? `SyntaxError: ${e.message}` : e;
+  }
+}
+
+test("a row end split across chunks, and a lone \r stays in its field", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+  expect(run(["a\r", "b"])).toEqual([["a\rb"]]);
+  expect(run(["a\r"])).toEqual([["a\r"]]);
+});
+
+test("a doubled quote or a closing quote split across chunks", () => {
+  expect(run(['"x"', '"y"', ""])).toEqual([['x"y']]);
+  expect(run(['"x"', ',y'])).toEqual([["x", "y"]]);
+});
+
+test("the BOM is dropped only at the very start of the input", () => {
+  expect(run(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(run(["a", "\uFEFFb"])).toEqual([["a\uFEFFb"]]);
+  expect(run(["\uFEFF"])).toEqual([]);
+  expect(run(["\uFEFF", "\n"])).toEqual([[""]]);
+});
+
+test("an empty input has no rows, a trailing row end adds none", () => {
+  expect(new CsvStream().end()).toEqual([]);
+  expect(run(["\n"])).toEqual([[""]]);
+  expect(run(["a\n", ""])).toEqual([["a"]]);
+});
+
+test("errors are SyntaxErrors with the parseCsv message, whatever the split", () => {
+  expect(outcome(() => run(["a\"", "b"]))).toBe(outcome(() => parseCsv('a"b')));
+  expect(outcome(() => run(['"a"', "b"]))).toBe(outcome(() => parseCsv('"a"b')));
+  expect(outcome(() => run(['"a"\r']))).toBe(outcome(() => parseCsv('"a"\r')));
+  expect(outcome(() => run(['"a"\r', "x"]))).toBe(outcome(() => parseCsv('"a"\rx')));
+  expect(outcome(() => run(['"a', "b"]))).toBe(outcome(() => parseCsv('"ab')));
+  expect(() => run(['"a'])).toThrow(SyntaxError);
+});
+
+test("matches parseCsv for random inputs and random splits", () => {
+  let seed = 1;
+  const rnd = () => {
+    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
+    return seed / 2 ** 32;
+  };
+  const alphabet = ['a', ',', '"', '\r', '\n', '\uFEFF'];
+  for (let t = 0; t < 3000; t++) {
+    let s = "";
+    const len = Math.floor(rnd() * 21);
+    for (let k = 0; k < len; k++) s += alphabet[Math.floor(rnd() * alphabet.length)];
+    const chunks: string[] = [];
+    for (let pos = 0; ; ) {
+      const n = Math.floor(rnd() * 5);
+      chunks.push(s.slice(pos, pos + n));
+      pos += n;
+      if (pos >= s.length) break;
+    }
+    const singles = s.split("");
+    expect(outcome(() => run(chunks))).toEqual(outcome(() => parseCsv(s)));
+    expect(outcome(() => run(singles))).toEqual(outcome(() => parseCsv(s)));
+  }
+});
+
+test("many small chunks give the same rows", () => {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (let i = 0; i < 200_000; i++) rows.push(...s.push(i % 2 ? "y\n" : "x,"));
+  rows.push(...s.end());
+  expect(rows.length).toBe(100_000);
+  expect(rows[0]).toEqual(["x", "y"]);
+  expect(rows.at(-1)).toEqual(["x", "y"]);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 11:00:33.306393684 +0000
+++ b/csv.ts	2026-10-29 11:02:04.649357108 +0000
@@ -50,3 +50,103 @@
   rows.push(row);
   return rows;
 }
+
+type State = "fieldStart" | "unquoted" | "unquotedCR" | "quoted" | "quoteInQuoted" | "afterClose" | "afterCloseCR";
+
+/** Reads the input of parseCsv a chunk at a time: push returns the rows that chunk finished, end returns the rest. */
+export class CsvStream {
+  private state: State = "fieldStart";
+  private field = "";
+  private row: string[] = [];
+  private offset = 0;
+  private crAt = 0;
+
+  push(chunk: string): string[][] {
+    const out: string[][] = [];
+    for (let k = 0; k < chunk.length; k++) this.feed(chunk[k]!, out);
+    return out;
+  }
+
+  end(): string[][] {
+    const out: string[][] = [];
+    if (this.state === "fieldStart" && this.row.length === 0) return out;
+    if (this.state === "quoted") throw new SyntaxError("a quoted field is still open at the end of the input");
+    if (this.state === "afterCloseCR") throw this.unexpected("\r", this.crAt);
+    if (this.state === "unquotedCR") this.field += "\r";
+    this.endRow(out);
+    return out;
+  }
+
+  private feed(c: string, out: string[][]) {
+    const at = this.offset++;
+    if (at === 0 && c === "\uFEFF") return;
+    this.step(c, at, out);
+  }
+
+  private step(c: string, at: number, out: string[][]) {
+    switch (this.state) {
+      case "quoted":
+        if (c === '"') this.state = "quoteInQuoted";
+        else this.field += c;
+        return;
+      case "quoteInQuoted":
+        if (c === '"') {
+          this.field += c;
+          this.state = "quoted";
+          return;
+        }
+        this.state = "afterClose";
+        this.step(c, at, out);
+        return;
+      case "afterClose":
+        if (c === ",") this.endField();
+        else if (c === "\n") this.endRow(out);
+        else if (c === "\r") {
+          this.state = "afterCloseCR";
+          this.crAt = at;
+        } else throw this.unexpected(c, at);
+        return;
+      case "afterCloseCR":
+        if (c !== "\n") throw this.unexpected("\r", this.crAt);
+        this.endRow(out);
+        return;
+      case "unquotedCR":
+        if (c === "\n") {
+          this.endRow(out);
+          return;
+        }
+        this.field += "\r";
+        this.state = "unquoted";
+        this.step(c, at, out);
+        return;
+      default:
+        // fieldStart or unquoted
+        if (c === '"') {
+          if (this.state === "unquoted") throw new SyntaxError(`a quote in a field that is not quoted, at offset ${at}`);
+          this.state = "quoted";
+        } else if (c === ",") this.endField();
+        else if (c === "\n") this.endRow(out);
+        else if (c === "\r") this.state = "unquotedCR";
+        else {
+          this.field += c;
+          this.state = "unquoted";
+        }
+    }
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+    this.state = "fieldStart";
+  }
+
+  private endRow(out: string[][]) {
+    this.endField();
+    out.push(this.row);
+    this.row = [];
+  }
+
+  private unexpected(c: string, at: number) {
+    return new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${at}`);
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.test.ts b/csv.test.ts
--- a/csv.test.ts	2026-10-29 11:03:07.483179580 +0000
+++ b/csv.test.ts	2026-10-29 11:05:52.365370645 +0000
@@ -23,3 +23,161 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+function streamAll(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const chunk of chunks) for (const row of s.push(chunk)) rows.push(row);
+  for (const row of s.end()) rows.push(row);
+  return rows;
+}
+
+function lcg(seed: number): () => number {
+  return () => {
+    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
+    return seed / 2 ** 32;
+  };
+}
+
+function expectStreamLikeParse(text: string, chunks: string[]): void {
+  let expected: unknown;
+  try {
+    expected = parseCsv(text);
+  } catch (e) {
+    expected = e;
+  }
+  if (expected instanceof SyntaxError) {
+    let actual: unknown;
+    try {
+      streamAll(chunks);
+    } catch (e) {
+      actual = e;
+    }
+    expect(actual).toBeInstanceOf(SyntaxError);
+    expect((actual as Error).message).toBe(expected.message);
+  } else {
+    expect(streamAll(chunks)).toEqual(expected as string[][]);
+  }
+}
+
+test("any split of any input gives parseCsv's rows or its SyntaxError", () => {
+  const alphabet = ["a", ",", '"', "\r", "\n", "\uFEFF"];
+  const rand = lcg(7);
+  for (let n = 0; n < 3000; n++) {
+    let text = "";
+    const len = Math.floor(rand() * 31);
+    for (let i = 0; i < len; i++) text += alphabet[Math.floor(rand() * alphabet.length)];
+    const chunks: string[] = [];
+    let from = 0;
+    for (let i = 0; i < text.length; i++) {
+      if (rand() < 0.3) {
+        chunks.push(text.slice(from, i));
+        from = i;
+      }
+    }
+    chunks.push(text.slice(from));
+    expectStreamLikeParse(text, chunks);
+    for (let cut = 0; cut <= text.length; cut++) expectStreamLikeParse(text, [text.slice(0, cut), text.slice(cut)]);
+  }
+});
+
+test("a row comes back as soon as its row end arrives", () => {
+  const s = new CsvStream();
+  expect(s.push("a\n")).toEqual([["a"]]);
+  expect(s.end()).toEqual([]);
+});
+
+test("a CRLF split across chunks is one row end", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+});
+
+test("a CR not followed by LF stays in its field", () => {
+  expect(streamAll(["a\r", "b"])).toEqual([["a\rb"]]);
+  expect(streamAll(["a\r"])).toEqual([["a\r"]]);
+});
+
+test("a doubled or closing quote split across chunks", () => {
+  expect(streamAll(['"x"', '"y"'])).toEqual([['x"y']]);
+  expect(streamAll(['"x', '"', '"y"'])).toEqual([['x"y']]);
+  expect(streamAll(['"x"', ",y"])).toEqual([["x", "y"]]);
+});
+
+test("text after a closing quote is rejected even in a later chunk", () => {
+  expect(() => streamAll(['"a"', "b"])).toThrow(SyntaxError);
+  expect(() => streamAll(['"a"\r', "x"])).toThrow(SyntaxError);
+  expect(() => streamAll(['"a"\r'])).toThrow(SyntaxError);
+});
+
+test("a quote in an unquoted field throws on the push that brings it", () => {
+  const s = new CsvStream();
+  expect(s.push("ab")).toEqual([]);
+  expect(() => s.push('"')).toThrow(SyntaxError);
+  expect(() => streamAll(["\uD83D", '\uDE00"'])).toThrow("at offset 2");
+});
+
+test("an open quoted field throws at end", () => {
+  const s = new CsvStream();
+  expect(s.push('"abc')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a BOM at the very start is dropped, one anywhere else is data", () => {
+  expect(streamAll(["\uFEFF", "a"])).toEqual([["a"]]);
+  expect(streamAll(["a\uFEFF"])).toEqual([["a\uFEFF"]]);
+  expect(streamAll(["\uFEFF"])).toEqual([]);
+});
+
+test("empty input and empty chunks give no rows", () => {
+  expect(streamAll([])).toEqual([]);
+  expect(streamAll(["", ""])).toEqual([]);
+});
+
+test("a trailing row end adds no row, empty fields are kept", () => {
+  expect(streamAll(["a\n"])).toEqual([["a"]]);
+  expect(streamAll(["\n"])).toEqual([[""]]);
+  expect(streamAll(["a,"])).toEqual([["a", ""]]);
+  expect(streamAll(["a,\n"])).toEqual([["a", ""]]);
+});
+
+test("a stream fed one character at a time over a long input equals parseCsv", () => {
+  const text = `"${"x".repeat(200000)}"\n${"a,b\n".repeat(100000)}`;
+  const s = new CsvStream();
