+test("agrees with a reference LRU and TTL model over random operations", async () => {
+  let seed = 1;
+  const rand = (n: number) => {
+    seed = (seed * 16807) % 2147483647;
+    return seed % n;
+  };
+  let t = 0;
+  const ttlMs = 50;
