+  // What each caller saw: its value, or the rejection, checked at the end.
+  const outcomes: Promise<void>[] = [];
+  for (let step = 0; step < 500; step++) {
+    const op = rand(10);
+    if (op < 4) {
+      const key = "abcde"[rand(5)]!;
+      const i = model.findIndex((e) => e.key === key);
+      if (i >= 0 && model[i]!.expires > t) {
+        model.push(...model.splice(i, 1));
+      } else {
+        if (i >= 0) model.splice(i, 1);
+        while (model.length >= max) model.shift();
+        model.push({ key, id: fnCalls++, expires: Infinity });
+      }
