+      );
+    } else if (op === 4) {
+      const key = "abcde"[rand(5)]!;
+      model = model.filter((e) => e.key !== key);
+      m.invalidate(key);
+    } else if (op === 5) {
+      model = [];
+      m.clear();
+    } else if (op < 9) {
+      const pending = [...Array(calls.length).keys()].filter((i) => !settled.has(i));
+      if (pending.length > 0) {
+        const id = pending[rand(pending.length)]!;
+        settled.add(id);
+        if (rand(4) === 0) {
+          calls[id]!.d.reject(new Error("x"));
+          model = model.filter((e) => e.id !== id);
+        } else {
+          calls[id]!.d.resolve(calls[id]!.key);
+          const e = model.find((e) => e.id === id);
+          if (e) e.expires = t + ttlMs;
+        }
+        await tick();
+      }
+    } else {
+      t += rand(60);
+    }
+    expect(m.size).toBe(model.length);
+    expect(calls).toHaveLength(fnCalls);
+  }
+  calls.forEach((c, i) => !settled.has(i) && c.d.resolve(c.key));
+  await tick();
+  await Promise.all(outcomes);
+});
